ee:message.ee:set-payload:
%dw 2.0
output application/json

// ================= VARIABLES =================

var category = vars.CategoryProduct default null

// ================= FUNCTIONS =================

fun mapProduct(item) = {
    id:       item.id as Number,
    name:     item.name,
    category: item.category,
    price:    item.price as Number,
    stock:    item.stock as Number
}

// ================= FILTRAGE =================

var safePayload =
    if (payload is Array)
        payload
    else
        []

var afterCategory =
    if (category == null)
        safePayload
    else
        safePayload filter (
            $.category == category
        )

// ================= MAPPING =================

---
afterCategory map (item) -> mapProduct(item)
